original": "永乐九年九月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b4d381c7-cd0b-5e95-82b7-f22ee44fe2d6"}, {"title": "朝廷减轻北京谪徙军民的赋役", "description": "永乐九年十月乙未，明廷减轻被贬谪迁到北京的军民所负担的赋税与差役。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "65a9037f-0560-5545-86e4-39fff9a98f99"}, {"title": "明廷册封哈密兔力帖木儿为忠义王", "description": "永乐九年十月癸卯，明廷封哈密的兔力帖木儿为忠义王。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "28333a12-1bd0-51f7-9ffc-ae6332672377"}, {"title": "明廷再次修纂《太祖实录》", "description": "永乐九年十月乙巳，朝廷再次组织修纂记录明太祖一朝政事的《太祖实录》。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "84c4140a-f7a9-5dbd-ac34-3889da207188"}, {"title": "明廷免除陕西积欠赋税", "description": "永乐九年十一月戊午，明廷豁免陕西积欠的赋税。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十一月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3cc58453-91ff-5aa5-9e50-baa21bb2933f"}, {"title": "张辅在生厥江击败对手", "description": "永乐九年十一月癸亥，张辅在生厥江击败与明军交战的部队。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十一月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b11f54b1-1ea7-513e-9efc-e85b0e6e1566"}, {"title": "朱瞻基被正式册立为皇太孙", "description": "永乐九年十一月丁卯，明成祖册立皇长孙朱瞻基为皇太孙。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十一月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1c08e7e0-6898-5def-8145-a60e5d822ad2"}, {"title": "韩观改镇交阯，葛森镇守广西", "description": "永乐九年十一月壬申，朝廷任韩观为征夷副将军，改派他镇守交阯，并命都指挥葛森镇守广西。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十一月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0745c117-a343-5378-a69e-56ab5bc8fea6"}, {"title": "明廷命司法官署及时处理囚犯", "description": "永乐九年十一月丙子，朝廷命司法官署及时处置已获罪的囚犯，避免案件和关押久拖。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十一月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c766f5aa-d977-5d75-b0cc-8388f14586f7"}, {"title": "朝廷派人督办掩埋战场遗骨", "description": "永乐九年十一月，明廷派使者监督掩埋暴露在战场上的遗骨。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4c53d0bc-eefe-5fbe-a555-f8b631fcd736"}, {"title": "明廷赦宥福余等三卫并令入贡", "description": "永乐九年十二月壬辰，朝廷赦宥福余、朵颜和泰宁三卫的罪责，并命它们入贡。", "start_year": 1411, "end_year": 1411, "time_original": "永乐九年十二月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cccf2267-b341-5b50-9a24-9e83b80c5cff"}, {"title": "明廷向各府部官员征询军民利弊", "description": "永乐九年闰十二月丁巳，明廷命各府部官员陈述军民事务中有利之处和需要治理的弊端。", "start_year": 1412, "end_year": 1412, "time_original": "永乐九年闰十二月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3694a08c-b9a0-5e99-9d17-987b4153ce42"}, {"title": "明廷派使赈济水灾和疫病所及地区", "description": "永乐九年，浙江、湖广、河南、顺天、扬州发生水灾，河南、陕西出现疫病。明廷派使者前往救济。 按原历纪年，事情发生在公元1411至1412年之间。", "start_year": null, "end_year": null, "time_original": "永乐九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f3bdfa3a-ff52-5e5a-8511-65b4db51f6d9"}, {"title": "满剌加王入朝", "description": "永乐九年，满剌加王来到明朝廷，本纪年末总记保存了这次入朝记录。 按原历纪年，事情发生在公元1411至1412年之间。", "start_year": null, "end_year": null, "time_original": "永乐九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1a546e38-9825-5d02-b888-59720c0704c9"}, {"title": "本纪汇记永乐九年多地入贡", "description": "永乐九年，爪哇、榜葛剌等地入贡，阿鲁台贡马，别失八里进献文豹，琉球中山三次入贡。本纪在年末合记，各次来使分属不同事项。 按原历纪年，事情发生在公元1411至1412年之间。", "start_year": null, "end_year": null, "time_original": "永乐九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "923cfc6b-803b-57aa-8379-cf7aafc35e59"}, {"title": "朝廷命入觐官员报告百姓疾苦", "description": "永乐十年正月己丑，明廷要求一千五百多名入觐官员分别报告民间困难。明廷规定，隐而不报者治罪，即使所言有不妥当之处也无需追究。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年正月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b833dd1b-125b-56f2-893e-d371933f8ee2"}, {"title": "明成祖在南郊举行祭祀大典", "description": "永乐十年正月丁酉，明成祖朱棣在南郊祭祀天地。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年正月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2005ea63-ee63-57b1-88a2-1df2e30b8bc6"}, {"title": "朝廷赈济平阳饥民并查办瞒报官员", "description": "永乐十年正月癸丑，朝廷救济平阳饥民，将未上报灾情的布政使及郡县官员逮捕查办。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年正月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bc73f492-8b31-52e7-b161-e4220872afc7"}, {"title": "山西、河南积欠赋税获免", "description": "永乐十年二月辛酉，明廷豁免山西、河南积欠的赋税。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年二月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "13950d45-91b9-521e-8f90-b0cbb00e8fb5"}, {"title": "明廷削减辽王朱植的护卫", "description": "永乐十年二月庚辰，辽王朱植获罪，朝廷削减他所属的护卫。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年二月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "15e6b567-73f6-57f6-9999-b801a9ade17d"}, {"title": "李彬在甘肃征讨八耳思朵罗歹", "description": "永乐十年三月丁亥，丰城侯李彬出兵征讨本纪所记的甘肃叛寇八耳思朵罗歹。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年三月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9f0fc55b-2cfe-54f8-96ea-b5d396768aa8"}, {"title": "明廷授予马铎等人不同等第的进士资格", "description": "永乐十年三月戊子，朝廷按不同等第授予马铎等人进士及第或进士出身。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年三月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c927abbb-7b93-5967-9197-8cbb96459b3e"}, {"title": "明廷免除北京水灾所涉租税", "description": "永乐十年三月甲辰，朝廷免征北京因遭遇水灾而涉及的租税。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年三月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f9d12c47-dabf-5b74-b0c3-7dc224a88f29"}, {"title": "明廷命查办见到民困而不报告的官员", "description": "永乐十年六月甲戌，明成祖告谕户部，地方官及朝廷派出的使者如亲眼见到百姓疾苦却未报告，须逮捕查办。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年六月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5074e802-36af-5575-ba9d-d02591d2c0fb"}, {"title": "朝廷禁止宦官干预官署政务", "description": "永乐十年七月癸卯，朝廷禁止宫中宦官干预应由主管官署处理的政务。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年七月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eef7b937-1aab-5344-9782-43fc0c31c790"}, {"title": "张辅在神投海击败交阯对手", "description": "永乐十年八月癸丑，张辅率军在神投海重创交阯一带与明军交战的部队。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年八月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "84f8633b-5d40-5fb2-aaec-e0518b49d84f"}, {"title": "明廷命边将从长安岭到洗马林修筑防御设施", "description": "永乐十年八月己未，朝廷命边将从长安岭向西直到洗马林修筑石墙，并加深壕沟。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年八月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5125219e-a7b8-52d6-8439-058a2d1167b2"}, {"title": "明成祖前往城南武冈打猎", "description": "永乐十年十月戊辰，明成祖前往城南的武冈狩猎。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年十月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "17b88ab2-dad3-5ce8-acee-a13ccc43c7ca"}, {"title": "侍讲杨荣奉命经略甘肃", "description": "永乐十年十一月壬午，侍讲杨荣受命到甘肃处理当地事务。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年十一月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "03333d67-2dc6-5074-a304-4ec1a60d4187"}, {"title": "郑和再次出使西洋", "description": "永乐十年十一月丙申，《明史》本纪记郑和再度出使西洋。卷末校勘记说明，此日旧作丙辰，因该月没有丙辰日，校为丙申。", "start_year": 1412, "end_year": 1412, "time_original": "永乐十年十一月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3f02bd10-5080-5f33-86d8-da4490a24f58"}, {"title": "本纪汇记永乐十年多地入贡", "description": "永乐十年，浡泥、占城、暹罗、满剌加、榜葛剌、苏门答剌、南浡利和琉球山南入贡。本纪用「球琉山南」记录最后一处。 按原历纪年，事情发生在公元1412至1413年之间。", "start_year": null, "end_year": null, "time_original": "永乐十年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c28520d9-e93f-5d3b-9869-a9effd3c6956"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

